import * as game from './core.mjs';
import {firebaseConfig,region} from './config.js';
import {createActionRunner} from './async-actions.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app');
let room=null,roomCode='',uid='',demo=false,demoPlayer=false,ownSubmission=null,unsub=null,backend=null,busy=false,edit=false,selected={},timerId=null;
let pending=null,sdkPromise=null,connectPromise=null,recoveryOpen=false;
const sampleNames=['Mina','Docteur VHS','La Momie'];
const sampleAnswers=[['Tim Burton','Jean Dujardin et Florence Foresti','Stéphane Bern','monstres/zombies','Des courgettes possédées qui veulent récupérer leur potager','Un légume bondit du bac à compost au ralenti','Des fils de pêche, beaucoup trop visibles','Une bataille de purée en apesanteur','La nuit des courgettes vivantes'],['Sofia Coppola','Marion Cotillard et Nicolas Cage','Un influenceur en live','épouvante','Une imprimante qui imprime votre futur avis de décès','Le toner explose au moment où tout le monde chuchote','Un fantôme en drap avec l’étiquette encore accrochée','Le démon exige une facture avec TVA','Bourrage papier : dernier avertissement'],['Guillermo del Toro','Alain Chabat et Adèle Exarchopoulos','Le stagiaire de la production','folklore','Le fantôme d’un maître-nageur municipal','Un sifflet retentit dans une piscine vide','Un monstre en mousse qui prend l’eau','Un exorcisme en aquagym synchronisée','Le pédiluve de la mort']];
let demoSubmissions={},demoVotes={};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const remoteActions=new Set(['create','start','beginReveal','revealNext','openVote','closeVote','nextQuestion','nextFilm','finish','vote','remove','retry','retryPlayer','skipImages']);
const actionLabels={create:'Création du salon…',start:'Démarrage de la partie…',beginReveal:'Ouverture des révélations…',revealNext:'Révélation de la réponse…',openVote:'Ouverture des votes…',closeVote:'Validation des votes…',nextQuestion:'Chargement de la suite…',nextFilm:'Chargement du film…',finish:'Préparation du palmarès…',vote:'Enregistrement du vote…',remove:'Mise à jour du casting…',retry:'Relance des images…',retryPlayer:'Relance des images…',skipImages:'Préparation des films…'};
function syncPendingUI(){
 let status=$('#pending');if(!status){status=document.createElement('div');status.id='pending';status.setAttribute('role','status');status.setAttribute('aria-live','polite');document.body.append(status);}
 status.hidden=!pending;status.textContent=pending?.label||'';
 app.setAttribute('aria-busy',String(!!pending));
 document.querySelectorAll('#app button,dialog button').forEach(button=>{
  const remote=remoteActions.has(button.dataset.action)||button.type==='submit'&&!!button.closest('form')||button.id==='confirmClose'||button.id==='confirmRetry'||button.id==='confirmSkip';
  if(pending&&remote){if(!('pendingDisabled' in button.dataset))button.dataset.pendingDisabled=String(button.disabled);button.disabled=true;const match=pending.form?button.closest('form')?.id===pending.form:pending.buttonId?button.id===pending.buttonId:button.dataset.action===pending.action&&(!pending.id||button.dataset.id===pending.id);button.classList.toggle('is-loading',!!match);if(match)button.setAttribute('aria-busy','true');}
  else if('pendingDisabled' in button.dataset){button.disabled=button.dataset.pendingDisabled==='true';delete button.dataset.pendingDisabled;button.classList.remove('is-loading');button.removeAttribute('aria-busy');}
 });
}
const actionRunner=createActionRunner({onStart(event){busy=true;const el=event?.currentTarget;const action=el?.dataset?.action;if(el?.tagName==='FORM')pending={form:el.id,label:el.id==='joinform'?'Connexion au salon…':'Enregistrement de votre film…'};else if(remoteActions.has(action)||el?.id?.startsWith('confirm'))pending={action,id:el?.dataset.id,buttonId:el?.id,label:actionLabels[action]||'Traitement en cours…'};syncPendingUI();},onEnd(){busy=false;pending=null;syncPendingUI();},onError(error){toast(['functions/deadline-exceeded','functions/unavailable'].includes(error.code)?'Le serveur met du temps à répondre. Vérifiez l’état du salon avant de réessayer.':error.message||'Une erreur est survenue.');}});
const safe=action=>actionRunner.wrap(action);
const isHost=()=>room&&room.hostId===uid&&!demoPlayer;
const isPlayer=()=>room?.players.some(p=>p.id===uid);
const stageKey=()=>room.phase==='films'?'final':String(room.question);
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Accueil"><span class="mark">7</span><span class="brandtext">LE SEPTIÈME<br><b>STREAM</b></span></button><nav class="toplinks"><button class="textbutton" data-action="rules">Les règles du jeu ↗</button>${room?`<button class="textbutton" data-action="project">${document.body.classList.contains('spectator')?'Vue classique':'Vue stream'}</button>`:''}<span class="edition"><i class="dot"></i>SPÉCIALE HALLOWEEN</span></nav></header>`;}
function footer(){return `<footer class="footer"><span>LE SEPTIÈME STREAM © 2026</span><span>DU CINÉMA. DES AMIS. DE TRÈS MAUVAISES IDÉES.</span></footer>`;}
function render(){const active=document.activeElement;const focus=active?.matches('textarea,input')?{id:active.id,name:active.name,value:active.value,start:active.selectionStart,end:active.selectionEnd}:null;clearInterval(timerId);app.innerHTML=`<div class="shell">${header()}${demo?`<div class="demobar"><span>MODE DÉMO · Joueurs et images de démonstration · Aucun appel IA</span><button data-action="demoRole">${demoPlayer?'Passer animateur':'Passer joueur'}</button><button data-action="leaveDemo">Quitter</button></div>`:''}${room?renderRoom()+generationPanel():landing()}${footer()}</div>`;bind();if(room?.phase==='writing'){tick();timerId=setInterval(tick,1000);}syncPendingUI();if(focus?.id){const next=document.getElementById(focus.id);if(next){next.focus({preventScroll:true});if(focus.start!=null&&next.setSelectionRange)next.setSelectionRange(focus.start,focus.end);}}}
function landing(){return `<main><section class="hero"><div><p class="eyebrow">LA SÉANCE QUE PERSONNE N’A DEMANDÉE</p><h1>LES<br>GOLDEN<br><span>MERDES.</span></h1><p class="intro">Le casting est douteux. Le scénario, catastrophique.<br>Et derrière cette très mauvaise idée… <strong>c’est vous.</strong> Créez le pire film d’Halloween et entrez dans la légende du nanar.</p><form id="joinform" class="entrycard"><div class="entrytop"><h2>PRENEZ VOTRE PLACE</h2><span>ENTRÉE LIBRE</span></div><label for="nickname">Votre pseudo à l’affiche</label><div class="inputrow"><input id="nickname" name="nickname" minlength="2" maxlength="24" autocomplete="nickname" placeholder="Ex. Comte Nanar" required><input id="code" name="code" maxlength="6" pattern="[A-Za-z0-9]{6}" aria-label="Code du salon" placeholder="CODE" autocomplete="off" value="${esc(new URLSearchParams(location.search).get('room')||'')}"></div><button class="primary full" type="submit">Rejoindre la séance <span>↗</span></button><p class="entrynote">Un pseudo, un code de salon. Pas besoin de compte.</p></form><div class="belowentry"><button class="textbutton" data-action="create">Vous animez la soirée ? Créer un salon ↗</button><button class="textbutton" data-action="demo">Essayer la démo →</button></div></div><div class="poster-area"><div class="poster-back"></div><img class="poster" src="./poster.svg" alt="Affiche rétro Les Golden Merdes : une silhouette approche d’un manoir devant une lune orange"><div class="seal">0 GLOBE.<br>100 % NANAR.<span>SÉLECTION OFFICIEUSE</span></div><div class="poster-caption"><span>FIG. 01 — L’AVANT-PREMIÈRE</span><span>TOUS PUBLICS, HÉLAS.</span></div></div></section><section class="steps" aria-label="Comment jouer"><div class="step"><span class="stepnum">01</span><div><h3>ÉCRIVEZ LE DÉSASTRE</h3><p>9 questions. 10 minutes pour imaginer<br>le film que personne n’oserait produire.</p></div></div><div class="step"><span class="stepnum">02</span><div><h3>LAISSEZ LA MAGIE OPÉRER</h3><p>L’IA maléfique invoque votre affiche et vos scènes.<br>Vos mauvaises idées prennent vie.</p></div></div><div class="step"><span class="stepnum">03</span><div><h3>ÉLISEZ LE PIRE DU PIRE</h3><p>Découvrez, votez, et couronnez<br>le grand nanar de la soirée.</p></div></div></section></main>`;}
function roomHeading(kicker,title,subtitle){return `<div class="pagehead"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="roomcode"><small>CODE DU SALON</small><b>${esc(roomCode)}</b><button data-action="copy">Copier l’invitation ↗</button></div></div>`;}
function players(){return `<div class="players">${room.players.map((p,i)=>`<div class="player"><span class="avatar" style="background:${['#414832','#4b352c','#343e46','#49402b'][i%4]}">${esc(p.name.slice(0,1).toUpperCase())}</span><div><b>${esc(p.name)} ${p.id===uid?'(vous)':''}</b><small class="${p.submitted?'ready':''}">${room.phase==='lobby'?'Prêt pour le tournage':p.submitted?`✓ Film envoyé · ${generationLabel(p.generation)}`:'Écriture en cours…'}</small></div>${isHost()&&room.phase==='lobby'?`<button class="textbutton" data-action="remove" data-id="${esc(p.id)}" aria-label="Retirer ${esc(p.name)}">×</button>`:''}</div>`).join('')}</div>`;}
function generationLabel(s){return ({idle:'en attente',queued:'images en attente',generating:'images en création',ready:'images prêtes',error:'images indisponibles',unavailable:'IA pas encore activée'})[s]||s;}
function generationPanel(){
 if(!isHost()||room.phase==='lobby')return '';
 const submitted=room.players.filter(p=>p.submitted),pendingImages=submitted.some(p=>['queued','generating'].includes(p.generation));
 const errors={credit_balance_exhausted:'Crédits API OpenAI épuisés',insufficient_quota:'Quota API insuffisant',rate_limit_exceeded:'Limite temporaire du fournisseur',generation_failed:'La génération a échoué'};
 return `<details class="panel recovery-panel" id="recovery" ${recoveryOpen?'open':''}><summary>Secours images <span class="small">· ${submitted.filter(p=>p.generation==='ready').length} / ${submitted.length} films prêts</span></summary><p class="note">Reprenez les images manquantes d’un joueur sans perdre celles déjà produites. Une relance ne contourne pas un manque de crédits ou une IA désactivée.</p><div class="recovery-players">${submitted.map(p=>`<div class="recovery-player"><div><b>${esc(p.name)}</b><span class="small">${p.generationCount??(p.generation==='ready'?3:0)} / 3 images · ${generationLabel(p.generation)}</span>${p.generationError?`<span class="small recovery-error">${esc(errors[p.generationError]||'Erreur de génération — relance possible')}</span>`:''}</div>${p.generation==='ready'?'<span class="statuspill">✓ PRÊT</span>':`<button class="secondary" data-action="retryPlayer" data-id="${esc(p.id)}">${['queued','generating'].includes(p.generation)?'Relance de secours':'Relancer les images'}</button>`}</div>`).join('')||'<p class="small">Les films apparaîtront ici après leur envoi.</p>'}</div><div class="controls"><button class="secondary" data-action="retry" ${!submitted.some(p=>['error','unavailable'].includes(p.generation)||['queued','generating'].includes(p.generation)&&Date.now()-(p.generationAt||0)>600000)?'disabled':''}>Relancer les films en échec ou bloqués</button>${room.phase==='reveal'&&room.question===8&&room.voteClosed&&pendingImages?'<button class="secondary" data-action="skipImages">Continuer sans attendre les images</button>':''}${demo?'<button class="secondary" data-action="simulateImageError">Simuler une panne d’images</button>':''}</div></details>`;
}
function renderRoom(){if(room.phase==='lobby')return `<main class="page">${roomHeading('ACTE I · AVANT LA SÉANCE','LES MAUVAISES IDÉES<br>SE RASSEMBLENT.',isHost()?'Partagez le code à vos invités. Quand tout le monde est là, lancez le tournage.':'Votre place est réservée. L’animateur lancera la partie quand tout le monde sera arrivé.')}<div class="layout"><section class="panel"><h2>LE CASTING <span class="small">· ${room.players.length} / 20 JOUEURS</span></h2>${room.players.length?players():`<div class="waiting">Les premiers cinéastes ne devraient plus tarder…</div>`}<div class="controls">${isHost()?`<button class="primary" data-action="start" ${room.players.length<2?'disabled':''}>Lancer les 10 minutes <span>→</span></button>`:`<span class="statuspill">EN ATTENTE DE L’ANIMATEUR</span>`}</div><p class="note">${isHost()?'L’animateur mène la séance et ne participe pas aux votes. Minimum : 2 joueurs.':'Gardez cette page ouverte pour suivre la partie.'}</p></section><aside class="panel"><h2>LE CONTRAT DU NANAR</h2><div class="rule"><strong>09</strong><span>questions pour inventer<br>un film franchement mauvais</span></div><div class="rule"><strong>10′</strong><span>pour écrire. Le temps écoulé<br>ne bloque jamais vos réponses.</span></div><div class="rule"><strong>+1</strong><span>point par vote reçu<br>à chaque question</span></div><div class="rule"><strong>+5</strong><span>points au film favori<br>du vote final</span></div><button class="textbutton" data-action="rules">Lire toutes les règles ↗</button></aside></div></main>`;
 if(room.phase==='writing')return writing();
 if(room.phase==='reveal')return reveal();
 if(room.phase==='films')return films();
 return results();}
function draft(){const saved=localStorage.getItem(`draft:${roomCode}:${uid}`);try{return saved?JSON.parse(saved):(ownSubmission?.answers||Array(9).fill(''));}catch{return Array(9).fill('');}}
function writing(){let me=room.players.find(p=>p.id===uid),a=draft();return `<main class="page">${roomHeading('ACTE II · LE SCÉNARIO',isHost()?'SILENCE,<br>ÇA INVENTE.':'ÉCRIVEZ VOTRE<br>CHEF-D’ŒUVRE RATÉ.',isHost()?'Les films se préparent. Vous gardez la main sur le début des révélations.':'Tout est permis, surtout les mauvaises idées. Vos réponses sont sauvegardées sur cet appareil.')}<div class="timer" id="timer"><div><span id="timerlabel">LE TEMPS FILE. LE GÉNIE, UN PEU MOINS.</span><small class="small">À zéro, vous pouvez toujours écrire et envoyer.</small></div><strong id="clock" aria-label="Temps restant">10:00</strong></div>${isHost()?`<div class="layout"><section class="panel"><h2>LE POINT SUR LES TOURNAGES</h2>${players()}<div class="controls"><button class="primary" data-action="beginReveal" ${room.players.some(p=>!p.submitted)?'disabled':''}>Passer aux révélations →</button>${demo?'<button class="secondary" data-action="simulate">Simuler les réponses des joueurs</button>':''}</div><p class="note">Les affiches se créent en arrière-plan pendant les révélations. Le vote de chaque question reste indépendant.</p></section><aside class="panel"><h2>LE SIGNAL DE DÉPART</h2><p class="small">${room.players.filter(p=>p.submitted).length} / ${room.players.length} films envoyés.</p><p class="note">Les dix minutes donnent le rythme. Attendez les derniers scénaristes, puis ouvrez les enveloppes.</p></aside></div>`:me?.submitted&&!edit?`<section class="panel"><p class="eyebrow">COPIE REMISE</p><h2>VOTRE NANAR EST DANS LA BOÎTE.</h2><p>Les images de votre film se préparent : ${generationLabel(me.generation)}.</p><p class="note">Vous pouvez encore corriger vos réponses tant que l’animateur n’a pas lancé les révélations.</p><button class="secondary" data-action="edit">Modifier mes réponses</button></section>`:`<form id="quizform"><div class="quizgrid">${room.questions.map((q,i)=>`<div class="question"><div class="qnum">QUESTION ${String(i+1).padStart(2,'0')} / 09</div><label for="q${i}">${esc(q.title)}</label><p>${esc(q.hint)}</p>${q.options?`<fieldset class="genres" style="border:0;margin:0;padding-left:0"><legend class="hidden">${esc(q.title)}</legend>${q.options.map(g=>`<label class="genre"><input type="radio" name="q3" value="${esc(g)}" ${a[i]===g?'checked':''} required>${esc(g)}</label>`).join('')}</fieldset>`:`<textarea id="q${i}" name="q${i}" maxlength="500" placeholder="${esc(q.example)}" required>${esc(a[i])}</textarea><span class="counter" data-counter="${i}">${a[i]?.length||0} / 500</span>`}</div>`).join('')}</div><div class="savebar"><span class="small" id="saved">Brouillon enregistré sur cet appareil · <span id="completed">${a.filter(x=>x?.trim()).length}</span> / 9 réponses</span><button class="primary" type="submit">${me?.submitted?'Enregistrer mes corrections':'Envoyer mon film'} <span>↗</span></button></div></form>`}</main>`;}
function tick(){const el=$('#timer');if(!el)return;const left=Math.max(0,600-Math.floor((Date.now()-room.startedAt)/1000));$('#clock').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;el.classList.toggle('warn',left<=300&&left>60);el.classList.toggle('urgent',left<=60&&left>0);el.style.setProperty('--remaining',`${left/6}%`);if(!left){$('#timerlabel').textContent='TEMPS ÉCOULÉ. LE TOURNAGE CONTINUE.';el.classList.remove('urgent');el.classList.add('warn');}}
function scorebar(){return `<div class="scorelist"><small>LE BOX-OFFICE</small>${[...room.players].sort((a,b)=>(room.scores[b.id]||0)-(room.scores[a.id]||0)).map(p=>`<span>${esc(p.name)} <b>${room.scores[p.id]||0} pt${(room.scores[p.id]||0)>1?'s':''}</b></span>`).join('')}</div>`;}
function voteButton(id){if(!room.voteOpen||!isPlayer())return '';if(id===uid)return '<p class="small">C’est votre film · pas d’auto-vote</p>';const chosen=selected[stageKey()]===id;return `<button class="secondary" data-action="vote" data-id="${esc(id)}">${chosen?'✓ Votre vote':'Voter pour cette réponse'}</button>`;}
function votingControls(){return `<div class="votefooter"><div><p>${room.voteOpen?`<span class="dot"></span>Les votes sont ouverts · ${room.voteCount} / ${room.players.length}`:room.voteClosed?'✓ Votes comptabilisés':room.phase==='films'?'Découvrez tous les films avant le vote.':'Les votes s’ouvriront après la dernière réponse.'}</p><small class="small">${room.phase==='films'?'+5 points au(x) film(s) en tête':'Chaque voix reçue rapporte 1 point'} · Pas de vote pour soi-même</small></div>${isHost()?`<div class="controls">${!room.voteOpen&&!room.voteClosed?`<button class="primary" data-action="openVote" ${(room.phase==='reveal'?room.revealed.length<room.players.length:room.filmIndex<room.players.length-1)?'disabled':''}>Ouvrir les votes →</button>`:room.voteOpen?`<button class="primary" data-action="closeVote">Clôturer les votes (${room.voteCount}/${room.players.length})</button>`:`<button class="primary" data-action="${room.phase==='films'?'finish':'nextQuestion'}">${room.phase==='films'?'Dévoiler le vainqueur ↗':room.question===8?'Dévoiler les films →':'Question suivante →'}</button>`}${demo&&room.voteOpen?'<button class="secondary" data-action="simulateVotes">Simuler les votes</button>':''}</div>`:''}</div>`;}
function reveal(){return `<main class="page"><div class="revealhead"><p class="eyebrow">ACTE III · QUESTION ${String(room.question+1).padStart(2,'0')} / 09</p><h1>${esc(room.questions[room.question].title)}</h1><p class="small">${room.revealed.length} / ${room.players.length} réponses dévoilées · ${isHost()?'À vous de faire durer le suspense.':'Place aux très mauvaises idées.'}</p></div><div class="answers">${room.players.map((p,i)=>{const a=room.revealed[i];return a?`<article class="answer ${selected[stageKey()]===p.id?'chosen':''}"><div class="player" style="padding:0;border:0;background:none"><span class="avatar">${esc(p.name[0])}</span><b>${esc(p.name)}</b></div><blockquote>« ${esc(a.answer)} »</blockquote>${voteButton(p.id)}${room.voteClosed?`<span class="tally">+${room.tallies[p.id]||0} point${(room.tallies[p.id]||0)>1?'s':''}</span>`:''}</article>`:`<div class="answer empty"><span class="display">?</span><span class="small">${esc(p.name)} · Réponse sous scellés</span></div>`;}).join('')}</div>${isHost()&&!room.voteOpen&&!room.voteClosed&&room.revealed.length<room.players.length?`<div class="controls"><button class="primary" data-action="revealNext">Dévoiler la réponse de ${esc(room.players[room.revealed.length].name)} →</button></div>`:''}${votingControls()}${room.question===8&&room.voteClosed&&room.players.some(p=>p.generation!=='ready')?`<p class="note">Images : ${room.players.filter(p=>p.generation==='ready').length} / ${room.players.length} films prêts. Les échecs pourront être présentés avec une affiche de remplacement.</p>`:''}${scorebar()}</main>`;}
function imageBlock(f,i,cls){if(f.images[i])return `<img class="${cls}" src="${esc(f.images[i])}" alt="${i===0?'Affiche':`Scène ${i}`} du film ${esc(f.title)}" loading="lazy">`;if(demo&&i===0)return `<img class="${cls}" src="./poster.svg" alt="Affiche de démonstration, illustration générique Les Golden Merdes">`;return `<div class="${cls} placeholder"><span class="display" style="font-size:40px">${i===0?'7':'◈'}</span><span>${demo?'VISUEL DE DÉMONSTRATION':'IMAGE INDISPONIBLE'}</span><span>${i===0?'Affiche':`Scène ${i}`}</span></div>`;}
function films(){const f=room.films[room.filmIndex];return `<main class="page">${roomHeading('ACTE IV · L’AVANT-PREMIÈRE','LE GRAND ÉCRAN.<br>LES PETITS BUDGETS.',`Film ${room.filmIndex+1} / ${room.films.length} · Une affiche et deux scènes pour admirer le désastre.`)}<div class="filmstage"><div>${imageBlock(f,0,'filmposter')}</div><section><span class="name">UN FILM DE ${esc(f.name).toUpperCase()}</span><h2>${esc(f.title)}</h2><span class="badge">${esc(f.tagline)}</span><div class="scenes">${imageBlock(f,1,'scene')}${imageBlock(f,2,'scene')}</div>${isHost()&&!room.voteOpen&&!room.voteClosed&&room.filmIndex<room.films.length-1?'<button class="primary" data-action="nextFilm">Film suivant →</button>':''}<p class="note">Le vote final récompense le film dans son ensemble : affiche, scènes et idée.</p></section></div>${room.filmIndex===room.films.length-1?`<div class="filmchoices">${room.films.map(f=>`<button class="secondary ${selected.final===f.id?'active':''}" data-action="${room.voteOpen&&isPlayer()&&f.id!==uid?'vote':'viewFilm'}" data-id="${esc(f.id)}">${esc(f.title)} ${room.voteOpen&&isPlayer()&&f.id!==uid?'· Voter':room.voteClosed?`· ${room.tallies[f.id]||0} voix`:''}</button>`).join('')}</div>`:''}${votingControls()}${scorebar()}</main>`;}
function results(){const winners=room.players.filter(p=>room.winners.includes(p.id));return `<main class="page winner"><p class="eyebrow" style="justify-content:center">PALMARÈS OFFICIEUSEMENT CATASTROPHIQUE</p><h1>ET LE GOLDEN<br><span>MERDE REVIENT À…</span></h1>${winners.map(p=>{const f=room.films.find(f=>f.id===p.id);return `<section><div class="winnerposter">${imageBlock(f,0,'filmposter')}</div><span class="badge">${room.scores[p.id]||0} POINTS · ${winners.length>1?'VAINQUEUR EX ÆQUO':'VAINQUEUR DE LA SOIRÉE'}</span><h2>${esc(p.name)}</h2><p class="intro" style="margin:12px auto">${esc(f.title)}</p><div class="scenes">${imageBlock(f,1,'scene')}${imageBlock(f,2,'scene')}</div></section>`;}).join('')}<div class="leaderboard">${[...room.players].sort((a,b)=>(room.scores[b.id]||0)-(room.scores[a.id]||0)).map((p,i)=>`<div class="rank"><span>${String(i+1).padStart(2,'0')} &nbsp; ${esc(p.name)}</span><strong>${room.scores[p.id]||0} points</strong></div>`).join('')}</div><p class="small">1 point par voix sur les questions · 5 points au(x) favori(s) du vote final</p><div class="controls" style="justify-content:center"><button class="secondary" data-action="export">Télécharger le palmarès</button><button class="primary" data-action="home">Retour à l’affiche ↗</button></div></main>`;}
function modal(content){const dialog=document.createElement('dialog');dialog.innerHTML=`<button class="close" aria-label="Fermer">×</button>${content}`;document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();return dialog;}
function rules(){modal(`<p class="eyebrow">LE SEPTIÈME STREAM PRÉSENTE</p><h2>LE GUIDE DU MAUVAIS FILM</h2><p>Rejoignez le salon avec un pseudo. L’animateur lance la partie : vous avez neuf questions pour créer votre film d’Halloween.</p><p>Le compte à rebours dure dix minutes. À zéro, rien n’est envoyé ni verrouillé. Vous pouvez corriger votre film jusqu’au début des révélations.</p><p>Chaque réponse est dévoilée une à une par l’animateur. Après chaque question, les joueurs choisissent une réponse : <strong>chaque voix reçue vaut un point.</strong> Vous pouvez changer votre vote tant qu’il est ouvert. L’animateur peut le clôturer même si certains joueurs n’ont pas voté.</p><p>Après la neuvième question, place aux affiches et aux deux scènes de chaque film. Un dernier vote attribue <strong>cinq points au film ayant le plus de voix</strong> (cinq à chacun en cas d’égalité). Sans voix, aucun bonus n’est distribué.</p><p>On ne vote pas pour soi. L’animateur ne vote pas. Le total désigne le vainqueur ; les ex æquo partagent la victoire.</p><p class="small">Les images de la démo sont des illustrations de remplacement. La vraie génération demande une connexion Firebase et une clé IA côté serveur.</p>`);}
function loadFirebaseModules(){if(!sdkPromise){const version='12.4.0';sdkPromise=Promise.all(['app','auth','firestore','functions'].map(name=>import(`https://www.gstatic.com/firebasejs/${version}/firebase-${name}.js`))).catch(error=>{sdkPromise=null;throw error;});}return sdkPromise;}
async function connect(){if(backend)return backend;if(connectPromise)return connectPromise;if(!firebaseConfig)throw new Error('Firebase n’est pas encore configuré. Essayez la démo pour découvrir le jeu.');connectPromise=(async()=>{const [a,auth,fs,fn]=await loadFirebaseModules();const instance=a.getApps().length?a.getApp():a.initializeApp(firebaseConfig),authInstance=auth.getAuth(instance);await authInstance.authStateReady();if(!authInstance.currentUser)await auth.signInAnonymously(authInstance);uid=authInstance.currentUser.uid;const invoke=fn.httpsCallable(fn.getFunctions(instance,region),'gameAction',{timeout:30000});backend={db:fs.getFirestore(instance),fs,call:async(action,data={})=>(await invoke({action,...data})).data};return backend;})().catch(error=>{connectPromise=null;throw error;});return connectPromise;}
async function watch(code){const b=await connect();roomCode=code;unsub?.();const unsubscribeRoom=b.fs.onSnapshot(b.fs.doc(b.db,'rooms',code),snapshot=>{if(!snapshot.exists())return;room=snapshot.data();if(!isHost()&&!isPlayer()){unsub?.();room=null;render();toast('Vous avez été retiré du salon.');return;}sessionStorage.setItem('activeRoom',code);render();},err=>toast(`Connexion interrompue : ${err.message}`));const unsubscribeAnswers=b.fs.onSnapshot(b.fs.doc(b.db,'rooms',code,'submissions',uid),snapshot=>{ownSubmission=snapshot.data()||null;},()=>{});unsub=()=>{unsubscribeRoom();unsubscribeAnswers();};}
async function command(action,extra={}){if(demo){applyDemo(action,extra);render();return;}const expected={phase:room.phase,question:room.question,filmIndex:room.filmIndex,voteOpen:room.voteOpen,voteClosed:room.voteClosed,revealedCount:room.revealed.length};const b=await connect();await b.call(action,{code:roomCode,...extra,expected});}
function startDemo(){unsub?.();demo=true;demoPlayer=false;uid='host';roomCode='NANAR7';room=game.newRoom('host');sampleNames.forEach((name,i)=>game.join(room,`demo${i}`,name));demoSubmissions={};demoVotes={};selected={};render();}
function applyDemo(action,data){switch(action){case 'start':game.start(room);break;case 'simulate':room.players.forEach((p,i)=>{demoSubmissions[p.id]={answers:sampleAnswers[i],images:[]};p.submitted=true;p.generation='ready';});break;case 'submit':{game.validateAnswers(data.answers);demoSubmissions[uid]={answers:data.answers,images:[]};const p=room.players.find(p=>p.id===uid);p.submitted=true;p.generation='ready';ownSubmission=demoSubmissions[uid];edit=false;break;}case 'beginReveal':game.beginReveal(room);break;case 'revealNext':game.revealNext(room,demoSubmissions);break;case 'openVote':game.openVote(room);demoVotes={};break;case 'vote':game.validateVote(room,uid,data.target);demoVotes[uid]=data.target;selected[stageKey()]=data.target;room.voteCount=Object.keys(demoVotes).length;break;case 'simulateVotes':room.players.forEach((p,i)=>{demoVotes[p.id]=room.players[(i+(room.question%2?2:1))%room.players.length].id;});room.voteCount=room.players.length;break;case 'closeVote':game.closeVote(room,demoVotes);break;case 'nextQuestion':game.nextQuestion(room,demoSubmissions,{skipImages:data.skipImages===true});break;case 'nextFilm':if(room.filmIndex>=room.films.length-1)throw Error('Dernier film.');room.filmIndex++;break;case 'finish':game.finish(room);break;case 'simulateImageError':{const p=room.players.find(p=>p.submitted);if(p){p.generation='error';p.generationCount=1;p.generationError='generation_failed';}recoveryOpen=true;break;}case 'retry':room.players.filter(p=>(!data.id||p.id===data.id)&&p.submitted&&p.generation!=='ready').forEach(p=>{p.generation='ready';p.generationCount=3;p.generationError=null;});toast('Images de démonstration rétablies. Aucun appel IA.');break;case 'remove':room.players=room.players.filter(p=>p.id!==data.id);break;}}
function bind(){$('#recovery')?.addEventListener('toggle',event=>{recoveryOpen=event.currentTarget.open;});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=safe(async()=>{const action=el.dataset.action;switch(action){case 'rules':rules();return;case 'home':if(room){modal('<h2>QUITTER LA SÉANCE ?</h2><p>La partie continue pour les autres joueurs. Le navigateur conservera votre accès au salon.</p><button class="primary" id="confirmHome">Retour à l’accueil</button>');$('#confirmHome').onclick=()=>{document.querySelector('dialog').close();unsub?.();room=null;demo=false;document.body.classList.remove('spectator');render();};}return;case 'demo':startDemo();return;case 'leaveDemo':room=null;demo=false;document.body.classList.remove('spectator');render();return;case 'demoRole':demoPlayer=!demoPlayer;uid=demoPlayer?'demo0':'host';ownSubmission=demoSubmissions[uid]||null;render();return;case 'project':document.body.classList.toggle('spectator');render();return;case 'copy':await navigator.clipboard.writeText(`${new URL('.',location.href).href}?room=${roomCode}`);toast('Invitation copiée.');return;case 'create':await connect();{const name=$('#nickname')?.value||'';const result=await backend.call('create');await watch(result.code);}return;case 'edit':edit=true;render();return;case 'viewFilm':{const f=room.films.find(f=>f.id===el.dataset.id);modal(`<h2>${esc(f.title)}</h2><p>Un film de ${esc(f.name)}</p>${imageBlock(f,0,'filmposter')}<div class="scenes">${imageBlock(f,1,'scene')}${imageBlock(f,2,'scene')}</div>`);}return;case 'vote':{const round=stageKey();await command('vote',{target:el.dataset.id});selected[round]=el.dataset.id;if(!demo)render();toast('Vote enregistré. Vous pouvez encore le changer.');}return;case 'retryPlayer':{const p=room.players.find(p=>p.id===el.dataset.id);if(['queued','generating'].includes(p.generation)){const d=modal('<h2>RELANCE DE SECOURS ?</h2><p>Une génération est encore signalée en cours pour '+esc(p.name)+'. La relance remplacera cette tâche en conservant les images déjà enregistrées. Un appel IA déjà parti peut encore se terminer et être facturé.</p><button class="primary" id="confirmRetry">Relancer les images manquantes</button>');$('#confirmRetry').onclick=safe(async()=>{await command('retry',{id:p.id,force:true});d.close();toast('Relance envoyée.');});}else{await command('retry',{id:p.id});toast('Relance envoyée.');}}return;case 'skipImages':{const d=modal('<h2>CONTINUER LA SÉANCE ?</h2><p>Les images disponibles seront affichées. Les autres apparaîtront automatiquement si leur génération se termine. Les votes et les scores sont conservés.</p><button class="primary" id="confirmSkip">Dévoiler les films maintenant</button>');$('#confirmSkip').onclick=safe(async()=>{await command('nextQuestion',{skipImages:true});d.close();});}return;case 'remove':await command('remove',{id:el.dataset.id});return;case 'closeVote':if(room.voteCount<room.players.length){const d=modal(`<h2>CLÔTURER CE VOTE ?</h2><p>${room.players.length-room.voteCount} joueur(s) n’ont pas voté. Les voix déjà reçues seront comptabilisées.</p><button class="primary" id="confirmClose">Clôturer malgré les absents</button>`);$('#confirmClose').onclick=safe(async()=>{await command('closeVote');d.close();});return;}break;case 'export':{const data=JSON.stringify({salon:roomCode,date:new Date().toISOString(),joueurs:room.players.map(p=>({pseudo:p.name,points:room.scores[p.id]||0,vainqueur:room.winners.includes(p.id)})),films:room.films},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`palmares-${roomCode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}return;}await command(action);}));
 $('#joinform')?.addEventListener('submit',safe(async(e)=>{e.preventDefault();const form=new FormData(e.target),code=String(form.get('code')).toUpperCase().trim();if(!/^[A-Z0-9]{6}$/.test(code))throw Error('Entrez le code à six caractères communiqué par l’animateur.');const b=await connect();await b.call('join',{code,name:form.get('nickname')});await watch(code);}));
 $('#quizform')?.addEventListener('input',()=>{const form=new FormData($('#quizform'));const answers=Array.from({length:9},(_,i)=>String(form.get(`q${i}`)||''));localStorage.setItem(`draft:${roomCode}:${uid}`,JSON.stringify(answers));$('#completed').textContent=answers.filter(x=>x.trim()).length;document.querySelectorAll('[data-counter]').forEach(el=>{el.textContent=`${answers[+el.dataset.counter].length} / 500`;});});
 $('#quizform')?.addEventListener('submit',safe(async(e)=>{e.preventDefault();const form=new FormData(e.target),answers=Array.from({length:9},(_,i)=>String(form.get(`q${i}`)||''));game.validateAnswers(answers);await command('submit',{answers});edit=false;toast(demo?'Film de démonstration enregistré.':'Film envoyé. La génération des images peut commencer.');if(!demo)render();}));}
render();
if(firebaseConfig){const preload=()=>loadFirebaseModules().catch(()=>{});if('requestIdleCallback' in window)requestIdleCallback(preload,{timeout:1500});else setTimeout(preload,300);}
if(firebaseConfig&&sessionStorage.getItem('activeRoom'))watch(sessionStorage.getItem('activeRoom')).catch(e=>toast(e.message));
